insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place)
values
(E'https://matcha-jp.com/cn/6362', E'zh-Hans', 33, E'【冈山】晴天之国新玩法！冈山与仓敷“恋爱＆水果甜蜜之旅”', E'拥有“晴天之国”之称的日本“冈山”，除了是日本传说桃太郎起源地外，还有那因日照充足、温暖气候而孕育出的优质水果，因而又有“水果王国”美名，更拥有超灵验的结缘神社呢！这次让我们边尝香甜水果，边为自己求个甜蜜恋情，甜度爆表冈山之旅现在就出发！\n\n位于日本中国地区的晴天之国“冈山县”，气候温暖，加上一年之中日照时间长，创造了水果理想的生长环境，因此冈山产的的水果，不论甜度、香气、滋味都是超高品质，可说是“极品三高水果”！而冈山更被冠上“水果王国”之盛名。\n\n除了美味水果，冈山也是中国地区的人气观光地，除了名胜美景，值得注目的还有超灵验结缘神社！这次让小编告诉你冈山新玩法：恋爱与水果的超甜蜜冈山之旅吧！\n\n冈山市的标准观光景点就是在日本100名城之一的“冈山城”与日本三大名园之一的“后乐园”，不过这次要去的结缘神社稍稍有点远，让我们电车出行吧。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/25-59162.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/25-59163.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/25-59146.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/02-59766.webp"]'::jsonb, E'2018-08-24'::timestamptz, E'冈山市'),
(E'https://matcha-jp.com/cn/6325', E'zh-Hans', 33, E'桃太郎别被岛根鸟取干掉了！六个魅力豆知识让你爱上冈山', E'岛根、鸟取、冈山三县，一向是中国地方（山阳山阴地区）讨论度最低的难兄难弟，前两者去年因为星巴克问题而突然成了媒体宠儿，独留冈山县落单，明明就是桃太郎神话的发源地，怎会落得乏人问津？今天就引介6个冈山魅力点，让你对冈山另眼相看！\n\n早开星巴克，错了吗～ 岛根鸟取因为观光产业并不发达，曾经分别沦为“最没存在感的县市排行”第1、8名，就连日本人都可能不知道这两县在哪里。虽然拥有鸟取沙丘、出云大社等自然文史名胜，但都是些年轻人不感兴趣的景点，在人口外移严重之下，这情况就越发严重了，甚至在这两个县里找不到一家星巴克。\n\n没有星巴克进驻，本来县民也习以为常，结果被日本电视台综艺节目“月曜から夜ふかし”一报导，竟然莫名其妙引起了全国关注，星巴克还真的跑去岛根展店，而且连开两家（因为岛根人口比较多，且刚好碰上出云大社平成大迁宫），鸟取于是成了“日本唯一没有星巴克的县”。\n\n日本人擅长自虐反向行销，常能化危机为转机，鸟取县知事后来一句“虽然没有星巴克，但是有沙丘（スタバはないけど、スナバはある）”不但立刻把日本人的注意力拉到鸟取沙丘上，也让星巴克在今年5月进驻鸟取，完成称霸日本全国的版图，鸟取1号店首日业绩更打破日本星巴克18年来的纪录，只能说地方的年轻人都很向往都市啊。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58541.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58543.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58544.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58545.webp"]'::jsonb, E'2018-08-24'::timestamptz, E'冈山市'),
(E'https://matcha-jp.com/cn/2531', E'zh-Hans', 34, E'从原爆圆顶馆到严岛神社，广岛旅游景点11选', E'是中・四国地方最大都市，又因坐拥和平纪念公园的原爆圆顶馆和宫岛的严岛神社2个世界遗产，成为不仅日本，而是全球知名都市的广岛，本文就要来介绍包含广岛城、广岛美术馆等11个知名观光景点。\n\n广岛市是中・四国地方最大都市，又因坐拥和平纪念公园的原爆圆顶馆和宫岛的严岛神社2个世界遗产，成为不仅日本，而是全球知名都市。\n\n实际上，广岛市内也有丰富的在地美食、购物景点，像是市内的牡蛎和广岛烧，还有宫岛的穴子鱼和红叶馒头。另外，在广岛车站周边也有本通商店街、SOGO、福屋、三越等百货公司，能让旅客好好地享受购物乐趣。\n\n此外，广岛境内也有许多历史性建物，像是知名的严岛神社，还有广岛城、三泷寺等诸多建物可观赏。还有像是缩景园、广岛县立美术馆、广岛现代美术馆等洋溢著艺术风情的景点。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/05/09-126318.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/09-126319.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/09-126321.webp","https://resources.matcha-jp.com/resize/720x2000/2022/05/09-126323.webp"]'::jsonb, E'2017-01-24'::timestamptz, E'宫岛'),
(E'https://matcha-jp.com/cn/26999', E'zh-Hans', 34, E'深入体验广岛的四条深度游路线 | 历史、美食与文化旅行指南', E'本文将介绍四条体验式旅游线路，让您从多个角度领略广岛的历史、美食和文化。从和平教育到夜间美食之旅，再到宫岛传统文化体验，我们将为您展现广岛的魅力，让您的旅程更加充实。\n\n近年来，让参与者在当地导游的带领下深入学习、品尝和感受的“体验式旅游”越来越受欢迎。例如，带领游客参观和平纪念公园和原子弹爆炸圆顶屋的徒步之旅，可以让您了解历史，体验广岛的重建历程及其对和平的承诺。\n\n本次旅行将带您参观和平纪念公园和和平纪念博物馆等重要景点，这两个景点均被联合国教科文组织列为世界遗产，让您更深入地了解广岛的过去及其和平的信息。\n\n此外，行程还包括一些简单的文化体验，例如折纸鹤，以及静思冥想的时间。漫步之后，您可以在折鹤塔顶层享用午餐，同时饱览广岛全景。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261781.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261795.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261796.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261783.webp"]'::jsonb, E'2026-03-28'::timestamptz, E'宫岛'),
(E'https://matcha-jp.com/cn/21945', E'zh-Hans', 34, E'【最新】尾道的魅力彻底解说！歴史、观光景点、美食、脚踏车跳岛一次体验', E'针对前往广岛县尾道市观光的旅客介绍尾道的基本资讯以及推荐的美食和饭店。拥有悠久历史的尾道有许多值得一看的地方，不论是骑自行车、参拜寺庙，或是巡访拍摄场景等，希望大家都能尽情享受愉快的时光。\n\n位于广岛县东南部的尾道市，是面向濑户内海的热门观光景点。无论是在濑户内岛波海道欣赏绝景、品嚐当地美食尾道拉麵，还是参观历史建筑，都能以各种方式尽情享受。\n\n尾道包括「坡道之城・尾道」区域、「濑户内岛波海道」区域和离岛区域，各自都有不同的魅力。尾道位于濑户内海的中央位置，北部有田园风光，南部则有岛波海道穿过。\n\n尾道于平安时代1169年被后白河院认定为庄园的停靠港，从那时起就因贸易船和航行船的往来而繁荣发展，是一座历史悠久的城市。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200491.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200492.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200493.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200494.webp"]'::jsonb, E'2024-10-08'::timestamptz, E'尾道'),
(E'https://matcha-jp.com/cn/5576', E'zh-Hans', 35, E'【山口县赏樱】樱花纷飞的篮球场下享青春！海景、美食通通有！', E'想好2018年要去哪里赏樱吗？不如来去日本山口赏樱吧！除了樱花秘境之外，一起尝河豚、荞麦面等美食，再顺道到山口锦带桥、角岛大桥、唐户市场等景点。跟着在地人游山口，满足赏樱、美景、美食的一日旅行！\n\n东京都内的赏樱景点都腻了吗？本篇介绍了山口县的赏樱人气景点，也提供了几处不为人知的赏樱秘境。想要留下最美好的赏樱回忆，同时也想要品尝山口县道地美食的访日旅客，参考这篇文章准没错！\n\n一提到山口县的樱花景点，许多人首先想到大多都是位于岩国市历史悠久的锦带桥。樱花与拱桥相互辉映所营造出来的古意风情也并非其他赏樱景点可以媲美。\n\n但在人挤人的桥上想要拍出一张美照，却得花上九牛二虎之力实在让人折腾。想要优雅赏樱又不想要人挤人的话，也可以开车兜风来去尝试看看以下的冷门赏樱景点。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/12/25-44921.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/25-44922.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/25-44920.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/25-44924.webp"]'::jsonb, E'2018-01-16'::timestamptz, E'角岛'),
(E'https://matcha-jp.com/cn/9460', E'zh-Hans', 35, E'【山口】日本规模最大的锺乳洞—秋芳洞，一起走进神秘的境界！', E'山口県的秋芳洞是日本规模最大的锺乳洞，长达约1公里的观光路线，隐藏着非常多美丽的景点，对於喜欢冒险的人，还可选择较不一样的路线。山口离广岛和福冈非常近，适合一起安排旅游。\n\n当大家前往广岛和福冈旅行时，也不妨把山口县的秋芳洞纳入旅程。为什么呢？让小编来告诉大家！\n\n秋芳洞是日本规模最大的锺乳洞，历史长达3亿5,000万年，走进洞窟将可以看到不同形状的钟乳石，在这里可以感受到大自然的奥妙。\n\n锺乳洞的意思系指石灰岩地质的地下洞窟，当石灰岩遇到酸性的水就会侵蚀渐渐形成钟乳石。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/02/20-97663.webp","https://resources.matcha-jp.com/resize/720x2000/2020/02/20-97664.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/09-99180.webp","https://resources.matcha-jp.com/resize/720x2000/2020/02/20-97646.webp"]'::jsonb, E'2020-06-09'::timestamptz, E'山口市'),
(E'https://matcha-jp.com/cn/7855', E'zh-Hans', 35, E'在山口县必做的13件事！〜元乃隅稻成神社、角岛大桥、河豚等〜', E'山口县有不少绝景，以及具文化特性的建筑物、温泉等相当有魅力的观光景点。这篇带大家去元乃隅稻成神社、角岛大桥等知名景点，还有品尝下关的河豚料理。\n\n山口县是日本都道府县中的中国地区最东边的县。极富历史感的萩城城下町、有着数座鸟居的元乃隅稻成神社，还有绝景的角岛大桥等，山口县的精彩，等你来挖掘。这里是日本不少伟人的出生地，因此，和伟人相关的史迹地点也不少！\n\n从东京到山口可以坐新干线。搭新干线从JR东京车站坐到JR新山口车站约4小时20分，单程20,100日元。从JR新山口车站坐到JR山口车站，请搭JR山口线约25分钟可以到，单程240日元。\n\n观光景点遍布全县各处，有驾照的朋友可以在山口车站租车旅游，会非常方便喔。快跟MATCHA小编一起逛逛吧。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85279.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85300.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85280.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85281.webp"]'::jsonb, E'2019-11-03'::timestamptz, E'角岛'),
(E'https://matcha-jp.com/cn/8207', E'zh-Hans', 36, E'【四国】日本四国自由行，交通、景点、美食去芜存菁推荐版', E'随着直航班机开通、濑户内国际艺术祭开办，【日本四国】一名越发响亮，跟东日本、关西地区、九州截然不同的人文风情、美食活动，慕名而来的游客年年增加。想要开启你的第一趟四国之旅吗？那就看一下小编的心血整理，预习预习吧！\n\n日本全体分成四大部分：北海道、日本本州、四国与九州。其中四国面积最小，如同名字由四个县组成，过去因为交通不便，观光人气不及其他地区，但随着濑户内国际艺术祭开办、直航飞机出现，越来越多人来到这里，感受其独特魅力。\n\n四国位于濑户内海区域，是岛国日本第四大岛屿，岛上分为香川县、爱媛县、高知县与德岛县，过去各县名称分别为讃岐国、伊予国、土佐国与阿波国，因此整座岛便被称为【四国】。\n\n因与日本本州的中国地区、近畿地区，及九州地区隔着海洋相望不相连，对外交通不易的四国，因而诞生有别于其他地方的文化风情。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/11/01-89531.webp","https://resources.matcha-jp.com/resize/720x2000/2019/11/01-89532.webp","https://resources.matcha-jp.com/resize/720x2000/2019/11/01-89533.webp","https://resources.matcha-jp.com/resize/720x2000/2019/11/01-89534.webp"]'::jsonb, E'2019-11-21'::timestamptz, E'阿波市'),
(E'https://matcha-jp.com/cn/12879', E'zh-Hans', 36, E'有机会获得德岛的特产品！学习德岛最大节庆「阿波舞」舞步，参加SNS线上大赛！', E'位在四国的德岛县，以美丽景致与充满夏日风情的「阿波舞」闻名。本文将介绍在家自学拥有400年历史阿波舞的方法，使用还有阿波舞音乐的SNS线上选拔大赛。得奖的参赛者将获赠德岛县特产品哦！\n\n本篇文章将介绍阿波舞的历史与特色，还有基本的跳法，以及可将自己跳阿波舞的影片上传投稿的期限限定活动阿波舞SNS大赛。入选优秀奖的话，将会赠送特产品「阿波蓝」制品！\n\n每年8月12日至15日，街上都会集结约10万名舞者，穿着鲜艳的服装，随着热闹的音乐声在街上跳着阿波舞。这个让德岛县民引以为豪的祭典至今已有400年以上历史。\n\n阿波舞最广为人知的便是女性舞者头上戴着的独特编织斗笠，不仅如此，男性穿着法被的模样也让人能深深感受到祭典氛围。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/09/19-146329.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/19-146330.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/19-146331.webp","https://resources.matcha-jp.com/resize/720x2000/2023/09/19-146333.webp"]'::jsonb, E'2023-11-01'::timestamptz, E'阿波市'),
(E'https://matcha-jp.com/cn/6762', E'zh-Hans', 36, E'来德岛县的西阿波体验400年不变的生活样貌', E'生活样貌从400多年前延续不变的德岛县西部「西阿波」。此地的人们在最大坡度40度的农地上从事农业维持生计。另外，作为商人的城市而繁荣的「卯建街道」也是一处保留日本昔日风情的地方。本次将介绍西阿波的魅力何在，还可以体验与现代截然不同的生活方式。\n\n位于日本西部、四国地方的德岛县除了从1586年持续至今的夏季祭典“阿波舞”，还有世界三大潮流之一的“鸣门的涡潮”，以及剑山和眉山等等名山，是一个可以感受日本传统与自然的好地方。明治时代以前，此地区被称为“阿波”，现在这个名字依旧可以在很多地方看到。\n\n※1：世界农业遗产……联合国粮食及农业组织(FAO)所认定，从事重要且传统的农林水产业地区。目前世界上有21国、52个地区获得认定。\n\n西阿波指的是徳岛县西部山地的美马市、三好市、剑町和东三好町的总称。散布此地的集落和从事农耕的人们生活样貌与食文化已经维持超过400年。可以说是在东京或大阪看不到的日本原风景。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/11/02-65683.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/02-65666.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/06-65911.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/02-65667.webp"]'::jsonb, E'2019-01-11'::timestamptz, E'东三好町'),
(E'https://matcha-jp.com/cn/7912', E'zh-Hans', 37, E'【小豆岛】徜徉在濑户内海最梦幻的小岛！景点与行程推荐', E'四国香川县的小豆岛是濑户内海最具代表性的岛屿之一，必去景点包括日剧《为了N》与《魔女宅急便》的拍摄地，还有情侣圣地天使之路及希腊风情橄榄公园等。可从神户，高松，冈山搭船前往，岛上可自驾或搭乘观光巴士轻松周游。\n\n在濑户内海众多小岛之中，小编最爱的当属小豆岛，拥有得天独厚的舒适气候及自然景色，甚至有日本的地中海美称。除了有不少日剧与电影都在这里拍摄之外，岛上也有丰富的观光景点可循览，跟着MATCHA小编来跳岛一下吧！\n\n如果没有国际驾照，不方便自驾的朋友，建议可以选择定期观光巴士。从2019年10月开始，费用改为4200日币（小孩2100日币），由小豆岛的土庄港出发与解散。途中会经过寒霞溪山顶，二十四个瞳电影村，橄榄公园等人气观光景点。另外也有包计程车与包巴士的选择，详细请见官网 更多精彩介绍 『高松』观光巴士一日券 轻松游日本版希腊小镇小豆岛 香川县\n\n小豆岛王道行程推荐给初访当地的旅人们。 早上十点先到天使之路感受海洋带来的浪漫气氛，再到小豆岛橄榄公园借一下扫帚在白色风车前跳跃于半空中，留念成为小魔女的瞬间。接近中午时到日本三大溪谷之一的寒霞溪欣赏绝景，搭乘空中缆车一览绝景。下山后吃碗在地特产爽口素面，下午可到酱之乡感受弥漫历史人文风情的老街，品尝酱油口味冰淇淋，接着到曾作为电影拍摄场景的二十四之瞳电影村，穿越时空回到昭和时代。 更多精彩介绍 高松旅游指南。从交通，景点到特产伴手礼，还有一天内可往返的离岛(小豆岛・直岛)资讯哦 香川县', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/11-85746.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/11-85748.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/11-85750.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/11-85751.webp"]'::jsonb, E'2019-10-04'::timestamptz, E'小豆岛'),
(E'https://matcha-jp.com/cn/7785', E'zh-Hans', 37, E'日本独特魅力大搜查！寻找「香川・女木岛」的艺术文化与咖啡厅', E'究竟什么才是日本的特色呢？东京和大阪等大都市，虽有不少有趣的东西，但大家别忘了日本的乡下也很厉害啊！这回小编要带大家认识日本规模最大的现代艺术祭典【瀬戸内国际艺术祭2019】舞台之一的“香川县女木岛”，让我们在这里找寻艺术的踪迹和特色咖啡厅吧。\n\n想请教各位日本迷，大家觉得日本的特色是什么呢？动漫？禅学？「卡哇伊」文化？高科技卫浴设备？还是客人至上的待客之道呢？\n\n以上其实不管哪一个都是日本特有的特徵，如果还要补充的话，小编认为还有一个就是“现代艺术”。例如香川冈山县的瀬戸内国际艺术祭、新泻县的大地艺术祭、小岛或农村举办的现代艺术祭典也可称为日本的特色之一。\n\n小编在2019年6月底，和发掘日本特色及推广“Cool Japan策略”的朋友，一起走访了香川县的女木岛。香川县是【瀬戸内国际艺术祭】的举行地之一(※)。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/08/12-83612.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/13-83762.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/12-83613.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/12-83614.webp"]'::jsonb, E'2020-01-13'::timestamptz, null),
(E'https://matcha-jp.com/cn/7360', E'zh-Hans', 37, E'【香川】日本最棒的夕阳！瀬户内海・父母滨海岸的五种玩法', E'香川县西部三丰市的父母滨海岸是拥有日本最高级夕阳美景的人气景点。但是，这里不只能拍到美景，还有可以玩海上独木舟的地点、品尝当地美食的咖啡店、很棒的Guest House和伴手礼商店喔！\n\nPicture coutesy of 三丰市 香川县西部三丰市的父母滨是2016年以来透过社群网站获得高人气的美景所在。特别是因为黄昏能欣赏到美丽的景色，被日本知名旅行杂志于2018年选为“想去的夕阳绝景排行榜”第1名。\n\n绝景的秘密在于退潮时海滩上出现的潮池。风弱的时候，潮池中的水就像一面镜子，映照出美丽的天空。\n\n潮池多半位在岩石处，但是父母滨海岸的沙滩上却可以看到很大的潮池。因为这样的特殊性孕育出奇迹美景。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76985.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76989.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76986.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/15-76987.webp"]'::jsonb, E'2019-06-16'::timestamptz, null),
(E'https://matcha-jp.com/cn/4371', E'zh-Hans', 38, E'保留日本古老街道风情的「小京都」，爱媛县大洲市的5个景点', E'京都，至今还保留有日本古街道！而您知道吗，在全日本中也有许多有着如同京都特色的小京都哦～本文章透过Google街景服务将要介绍玩乐大洲市的魅力。\n\n京都，保存有日本古街道！而你知道，在全日本中也有许多有着如同京都特色的小京都吗。\n\n有一称是”伊予(※a1)的小京都”爱媛县南部城市“大洲市”。本文章透过Google街景服务，将要介绍玩乐大洲市的5大重点。\n\n大洲市内中心有着建于1331年的“大洲城”，曾作为城下町而发展。由于建筑老化之故，当初建成的天守阁(※2)已经毁损，现今看到的是于2004年所复建而成。可从天守阁眺望大洲市街景。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/04/26-25268.webp"]'::jsonb, E'2017-06-06'::timestamptz, E'大洲市'),
(E'https://matcha-jp.com/cn/8089', E'zh-Hans', 38, E'沿爱媛岛波海道走！单车女子跳岛之旅', E'走访过旅游书上介绍的四国热门景点，不如从爱媛道后出发，来场自行车跳岛之旅！在濑户内岛波海道间，感受自行车飞驰的快感，利用两日一夜的时间就把濑户内海五个岛屿一次性走完，寻访四国不一样的魅力景点。\n\n你是否也向往着在日本宽敞道路上，踩着脚踏车欣赏景点风景？这次和MATCHA小编从爱媛县的今治市出发，展开一场自行车女子的跳岛之旅，远离忙碌都市生活吧！本篇不介绍热门的四国景点，改用自行车为交通工具走往岛波海道，感受自行车飞驰的快感，利用两日一夜的时间就把濑户内海五个岛屿一次走完！\n\n第一站前往大岛。你知道“日本三大湍急海潮”吗？其中一个就在大岛的来岛海峡。早上，在吉海新鲜馆餐厅(よしうみいきいき馆)内购买观潮船的门票，出发到下田水港准备登上观潮船（从港口步行约3至5分钟）。\n\n整个急流观潮体验之旅需时约40分钟，旅客可以从中近距离观赏到全球首座三连式的吊桥－－“来岛海峡大桥”，还有湍急的海峡海潮。此外，还可以在旅途中看到各个与昔日村上水军犹有关系的岛屿，以及被称为“日本海事都市”的今治造船厂群，这都是平日难得一见的美景。 下田水港渡轮码头', E'["https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87990.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87991.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87992.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87993.webp"]'::jsonb, E'2019-12-02'::timestamptz, E'今治市'),
(E'https://matcha-jp.com/cn/5645', E'zh-Hans', 38, E'聊一聊爱媛县松山市民的心头好点心：“日切烧”', E'爱媛县松山市的泽井本舗“ひぎりやき”，是当地知名的传统甜点店。“ひぎり茶屋 大街道店”则有最丰富口味的日切烧。本文为大家介绍日切烧的美味，以及泽井本铺大街道店。\n\n面粉作成的饼皮中，塞满红豆馅的甜点“日切烧”。位于爱媛县松山市的“泽井本舗”制作，销售着这个松山市自古以来就有的传统甜点。\n\n日切烧原大约于100年前，在松山市内的一间“善胜寺”所卖的甜点。其名称来自于寺内的一尊“日切地藏王菩萨”。开卖以来，一直是这里的居民喜爱的甜点。\n\n刚做好的日切烧，外皮酥脆，内馅软嫩的口感，即使是日式点心中常见的红豆口味，一口咬下去在嘴巴中化开来的滋味，令人忍不住地一个接着一个吃。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/01/14-45933.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/14-45934.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/14-45935.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/14-45937.webp"]'::jsonb, E'2018-04-02'::timestamptz, E'松山市'),
(E'https://matcha-jp.com/cn/7851', E'zh-Hans', 39, E'在高知想拥有的十种体验(绝景、历史景点、美食等汇总)', E'位于四国地方的高知县是一处历史悠久、自然优美且可以品尝美味的地方。本篇介绍高知引以为豪的名胜地、桂滨、仁淀川，以及和伟人坂本龙马有关的景点、可品尝美味拍松鱼肉的市场、柚子知名产地等。\n\n位于四国地方的高知县以优美自然和可口美食知名。以美丽蓝色被誉为“仁淀蓝”的仁淀川、四面松树绿荫与碧蓝大海的对比十分醒目的桂滨等都是必游的名胜地。\n\n至于美食，瘦肉鲜美的鲣鱼、清香宜人的柚子等十分出名。将鲣鱼刺身表面轻微炙烤的菜肴“拍松鲣鱼”是一道必尝菜。\n\n高知是在日本格外有名的一位武士、坂本龙马的家乡，故而与龙马有渊源的史迹众多。以下介绍在高知想要拥有的十种体验。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/02-85065.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/13-101271.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/10-101196.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/10-101197.webp"]'::jsonb, E'2020-05-30'::timestamptz, E'高知市'),
(E'https://matcha-jp.com/cn/4125', E'zh-Hans', 39, E'『高知』迟开的向日葵拍摄景点：日本最后清流 四万十川自行车散策', E'安排一趟四国高知之旅，远离都市尘嚣，亲近大自然，到由生田斗真主演日剧“迟开的向日葵”拍摄景点，被称为土佐的小京都“中村”，于碧绿山景间的四万十川河域边骑自行车，感受一下久违地宁静气氛吧！\n\n在四国高知县西部四万十川，周围没有过多开发，保有河川最原始朴质风貌，有着“日本最后清流”之称。总长196公里，也是四国境内最长的河川。租辆自行车，乘着微风而行，沿途欣赏四万十川河水透彻之美，度过优闲的午后时光吧！\n\n550年前，古代诸侯土佐一条氏为了躲避内乱，从京都跑到土佐(高知县旧称土佐国)，在当地仿效京都规划城镇、兴建街道，因此中村又有“土佐的小京都”之称。\n\n从高知县市区搭乘JR到中村站，车程近2小时，可以选择坐巴士、开车、乘船一览四万十川之美，但以自行车方式，用最适合自己的速度，亲近这片原始自然风景。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/04-20497.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/04-20496.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/04-20512.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/04-20498.webp"]'::jsonb, E'2017-08-03'::timestamptz, E'四万十川'),
(E'https://matcha-jp.com/cn/5489', E'zh-Hans', 39, E'【高知】照着走就对了！文化美食轻旅行ㄧ日行程', E'高知，位置四国的南部，也是四国4县中面积最大，古时称为“土佐”。好多人认识高知，是因为坂本龙马。或是因为“日本最后一条清流”的四万十川而认识高知。这次小编带大家去高知，来一次高知的一日旅行，把高知的景点、历史、文化到美食都认识一遍。\n\n“桂浜”本来就是高知人的赏月名所，那为什么和坂本龙马拉上关系呢？坂本龙马是高知出身，因为推动维新革命，而遭到刺杀，死时只有29岁。身为维新志士的他，当年就是站在桂浜这片海滩上，立下改革日本的大志愿。现在桂浜也耸立了一尊坂本龙马的像，以纪念当初那个望海立志的年轻人。\n\n海岸旁边有座“坂本龙马记念馆”，除了可了解坂本龙马的生平以外，还可以认识日本“明治维新”这一段重要的历史。 location_on 桂滨\n\n竹林寺供奉了文殊菩萨，是佛教4大菩萨之一。前往竹林寺，可从JR高知站出发，搭乘高知“MY BUS”，约半小时车程。停留约1小时左右，再搭乘午后的巴士回到高知站。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/12/11-43503.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/11-43502.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/12-43582.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/12-43583.webp"]'::jsonb, E'2018-01-05'::timestamptz, E'四万十川'),
(E'https://matcha-jp.com/cn/1354', E'zh-Hans', 40, E'饱览北九州之秋！福冈红叶景点9选', E'福冈以优美自然、热心肠的人们还有众多美食而知名。在秋天来访福冈的话，请一定要去看红叶！ 本篇介绍九处秋天来访福冈必定想参观的红叶景点。\n\n位于九州地方北部的福冈，以优美自然、热心肠的人们还有众多美食而知名。 若是秋天来访福冈的话，请一定去观赏红叶。本篇介绍秋天来访福冈绝对会想去的八处红叶景点。\n\n福冈例年的红叶观赏时期为11月上旬〜11月下旬(有些地方为12月上旬)前后。请注意根据当年气候和地区而定，红叶观赏时期略有不同。\n\n7.修行场红叶层染的「英彦山神宫」 11月上旬〜11月中旬 8.园内看点众多的「白野江植物公园」 11月下旬〜12月上旬 9.御船山乐园 11月上旬〜12月上旬 1.从博多前往十分便利的「舞鹤公园」 Picture courtesy of 福冈市', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58455.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58553.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58458.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58457.webp"]'::jsonb, E'2018-10-07'::timestamptz, E'福冈市'),
(E'https://matcha-jp.com/cn/22211', E'zh-Hans', 40, E'搭福冈地铁玩透福冈市区！路线图、沿线景点、优惠车票、信用卡搭车资讯彙整', E'福冈市区内的交通搭乘搭福冈地铁是最方便的，本文要介绍福冈地铁的路线、优惠票券与搭乘方式，还有最重要的沿线人气旅游景点，一起搭地铁玩福冈市区吧！\n\n只要利用福冈市的地铁，再配合JR和西铁的话，福冈市区的交通可以说是相当方便，旅客们可以轻松游玩市区景点和购物。\n\n福冈地铁的起跳价是大人210日圆，后依照里程收费，最高单趟收到380日圆，适用SUICA、PASMO、ICOCA等全国通用的交通卡。\n\n如果只在市区搭乘福冈地铁，地铁的售票机有贩售一日券，一日券价格大人640日圆，小孩320日圆，已正常情况下只要搭乘三次就回本。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204379.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/23-204594.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/23-204632.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/28-205844.webp"]'::jsonb, E'2024-10-29'::timestamptz, E'福冈市'),
(E'https://matcha-jp.com/cn/5790', E'zh-Hans', 40, E'【福冈】地表最强福冈美食地图攻略！当地人美味清单39选', E'一提到日本九州地区的美食之都“福冈”，让人想到的就是数不尽的美食！这篇整理了来到福冈必吃的豚骨拉面、牛肠内脏锅、水炊鸡肉锅、乌冬面还有屋台等传统福冈美食，另外还介绍了法式松饼、鲷鱼烧、梅枝饼等超夯甜品与时尚咖啡厅。无论是想要去特色屋台、居酒屋或是想要将美食带着走，看完这篇福冈美食地图，包准让你第一次游福冈就上手！\n\n本篇以介绍「福冈」整体区域的美食为主，若想要进一步深度了解「博多站」周边的吃喝玩乐住宿，建议可以事先参考下面文章喔！ 更多精彩介绍 【福冈】初学者看过来！ “博多”上班族的美食购物住宿地图 福冈县\n\n另外，若想要短期间内攻略福冈市内与郊区的人气旅游景点的话，则可以参考下方的福冈旅游懒人包！\n\n福冈人也爱吃锅，其中则以「水炊鸡肉锅」与「牛肠锅」最受当地人的喜爱。水炊鸡肉锅由于所使用的鸡肉高汤比较清淡，因此整体的味道偏向清新不腻口的口感。牛肠锅则依照各间专卖店的风格而异，有原味、味噌、酱油等等口味的汤底，无论是哪种汤底品嚐起来都是比较偏向浓郁的口感。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/02/20-48581.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/20-48583.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/22-48937.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/20-48585.webp"]'::jsonb, E'2018-06-02'::timestamptz, E'福冈市'),
(E'https://matcha-jp.com/cn/7306', E'zh-Hans', 41, E'九州・佐贺不可错过的15件事：摄影圣地、美食、购物一样都不能少', E'位于九州北部的佐贺县，每年会举办充满各种色彩的国际热气球大赛，也拥有例如美丽梯田等绝美景色，更少不了包括佐贺牛在内的美食和可以大肆血拼的奥特莱斯。是来九州旅游绝对不能错过的地方。\n\n五彩缤纷的热气球节、浮于水面的红色鸟居，壮美的梯田景色等独此一处的美景。奥特莱斯购物村、充满艺术气息的图书馆等日本流行的时尚先锋地。新鲜的海鲜、鲜美多汁的和牛肉等美食……。\n\n想要一次体验到全部，就只有到位于九州的佐贺来才能实现了。今天就给大家介绍只有在佐贺才能够体验的吃喝玩乐，赶快来看一下吧！\n\n首先，让我们来认识一下佐贺吧。佐贺县位于九州的北部地区，东边接邻九州的门户福冈，西边则是以豪斯登堡、充满风情的街道而闻名的长崎。 黄色的标记就是九州的佐贺国际机场', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75929.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75911.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75371.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/17-75372.webp"]'::jsonb, E'2019-06-03'::timestamptz, E'佐贺市'),
(E'https://matcha-jp.com/cn/21465', E'zh-Hans', 40, E'【九州】天气特征解析！介绍四季服装搭配与推荐活动', E'我们将介绍被认为是温暖的九州各县的气候特征。由于九州南北延伸，因此不同地区的气候会有所不同。除了各县的气候特征外，还整理了每个月的平均气温和湿度数据。此外，还提供了各季节适合的服装以及热闹的活动信息。\n\n自从决定前往九州旅行以来，您是否一直专注于「去哪儿」和「吃什么」？与受欢迎的景点和美食同样重要的是天气。九州南北长，四面环海，山脉众多，不同区域的气候差异很大。本文将根据各个县的天气进行解说，并介绍适合各季节的服装和热门活动。\n\n九州位于日本的西南部，气候被认为是温暖的，但由于北部有东西延伸的山脉，而中南部也有南北的山脉，气候会有所不同。\n\n如果气温比预期低，在旅行中可能会感到「应该多带些暖和的衣服」，这会减少旅行的乐趣。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195617.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195619.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195620.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/05-195621.webp"]'::jsonb, E'2024-09-05'::timestamptz, null),
(E'https://matcha-jp.com/cn/9568', E'zh-Hans', 40, E'福冈OUTLET购物指南！交通，好物，优质商家小编帮你轻松总结', E'近年来人气飙涨的九州城市“福冈”，不仅是美食的天堂，便利的购物设施更是让你买到手软！曾久住福冈的MATCHA小编发自内心评价：真的是很方便购物的地方啊。今天就让小编告诉你福冈OUTLET包括THE OUTLETS 北九州、福冈玛莉诺亚城、鸟栖PREMIUM OUTLETS及百货购物中心的地图！\n\n从九州玄关福冈机场到市区坐地铁只要5分钟的福冈，近年来在国内外游客中非常有人气，除了遍地的美食，购物设施也是应有尽有！今天就让小编特选出福冈县内与市区的OUTLET及百货公司，福冈购物完整地图就看这里！\n\n其实福冈周遭的OUTLET有三家：THE OUTLETS 北九州、福冈玛莉诺亚城与鸟栖PREMIUM OUTLETS。\n\nTHE OUTLETS 北九州于2022年4月全新开幕，是九州最大级的商业设施，从福冈市区的博多车站或是从小仓车站搭乘JR至太空世界车站都十分便利，从山口县的下关车站前来也只要约30分钟，甚至还设有北九州机场联络巴士，可以说是交通最为便利的购物天堂。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127833.webp","https://resources.matcha-jp.com/resize/720x2000/2022/06/22-127837.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99804.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/19-99805.webp"]'::jsonb, E'2022-11-08'::timestamptz, E'福冈市'),
(E'https://matcha-jp.com/cn/10410', E'zh-Hans', 41, E'【九州地区】佐贺鹿岛酒飘香！让人微醺沉醉的百年酒文化', E'在日本九州地方的佐贺县有一处名副其实的酒之乡—鹿岛市，与其相邻的嬉野也早已备好丰富的美酒佳肴等候大家的光临。文中本为大家精心设计了2天的酒藏之旅，和小编一起开启这段微醺之旅吧。\n\n九州地区佐贺县的鹿岛市，这里的百姓代代以酿酒为生，可以说是名副其实的酒之乡。 鹿岛市内不少的酿酒厂都拥有200年以上的历史，其中还有几间酒厂对外开放，若是酒香难耐，不妨走进这里品味日本的百年幽香。\n\n在这两天的鹿岛嬉野酒藏之旅中，漫步在江户时代的街道上，品尝着各式各样的美酒和当地美食，还可以体验酿酒过程呢！\n\n第一天，在日本三大拉面之街—福冈县的博多与导游会合。想到接下来能体验的美酒和美食，内心兴奋不已，大伙儿一同搭上计程车，出发前往鹿岛。', E'["https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112555.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/24-112578.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112537.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112538.webp"]'::jsonb, E'2021-03-09'::timestamptz, E'鹿岛市'),
(E'https://matcha-jp.com/cn/5037', E'zh-Hans', 41, E'【佐贺】真正的图书馆革命！ 茑屋,星巴克进驻的武雄市图书馆', E'全日本首座公营与私营合作的佐贺县武雄市图书馆。市长樋渡启祐先生，有天看到电视台介绍茑屋书店（TSUTAYA)，请朋友代为联络社长增田宗昭先生见面，希望将武雄市图书馆重新的包装，包括进驻星巴克,吸引更多市民喜欢到图书馆。而增田社长其实也一直有意与图书馆合作，于是就这样一拍即合！\n\n说这里起了革命，是因为这里是全日本首座公营与私营合作的图书馆。佐贺县武雄市市长樋渡启祐先生，有天看到电视台介绍代官山的茑屋书店（TSUTAYA)，请朋友代为联络社长增田宗昭先生见面，希望将武雄市图书馆重新的包装，吸引更多市民喜欢到图书馆。而增田社长其实也一直有意与图书馆合作，于是就这样一拍即合！\n\n走进图书馆内，宽敞且明亮，因为这里采用了无缝空间的概念，尽量都不用太多支撑物，增加空间感。使用了木地板与柔和的黄灯，这轻易增加了温暖感，让本来给人严谨冰冷的图书馆，变成一个平易近人的阅读空间。\n\n这个公私合作的图书馆，在很多人眼中都是不可思议，因为要取得平衡点实在不容易。在武雄市和CCC(茑屋书店的母公司“Culture Convenience Club”）的努力下，图书馆在2013年4月重新开幕后，仅仅3个月便创下26万的入场人数纪录，每天来馆人数平均有2900人，是上一年度的4倍，而武雄市的市民大约有5万人左右。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/09/13-36032.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/13-36031.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/13-36033.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/13-36034.webp"]'::jsonb, E'2018-09-06'::timestamptz, E'武雄市'),
(E'https://matcha-jp.com/cn/3913', E'zh-Hans', 42, E'长崎人地观光地详细指南！抹茶精选长崎29处旅游景点', E'位于九州地方西北部的长崎县是日本富有外国风情的人气观光地。长崎有历史悠久的观光景点与日本三大中华街之一的长崎新地中华街等众多观光地。本篇文章将向大家介绍长崎县的各个经典景点与不为人知的绝佳观光场所。\n\n位于九州地方西北部的长崎是东西文化交汇，富有异国风情的城市。同时，这里也是第二次世界大战原子弹的投掷点，因此这里和广岛一样, 在世界上也有一定的知名度。\n\n长崎有许多历史景点，本篇文章将向大家介绍在长崎旅游时推荐前往的观光旅游好去处29个。\n\n如果是从东京、大坂到长崎的话可以直接搭乘飞机至长崎机场，再搭乘巴士到长崎市区或其他地区都很方便。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129752.webp","https://resources.matcha-jp.com/resize/720x2000/2023/10/06-147944.jpeg","https://resources.matcha-jp.com/resize/720x2000/2020/04/07-100975.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/07-100978.webp"]'::jsonb, E'2017-04-26'::timestamptz, E'长崎市'),
(E'https://matcha-jp.com/cn/5858', E'zh-Hans', 42, E'长崎夜景尽收眼底！欣赏夜景的好地方推荐&绝品美食', E'夜游长崎，当然不能错过夜景和美食喽。在稻佐山、锅冠山公园、“出岛Wharf”欣赏完美丽夜景后，去品尝当地特色美食吧！本次为大家介绍经典美食"土耳其饭（トルコライス）"和"日式什锦面（强棒面，长崎ちゃんぽん）"，以及港町・长崎的居酒屋才有的特色海鲜料理和长崎名物"关东煮（おでん）"。吃个夜宵再回酒店休息吧～\n\n九州地方的长崎市，作为江戸时代日本唯一向海外开放的海港城市发展至今，十分繁荣。也受到欧洲和中国的影响，长崎形成了独特的文化，即使身在日本也能感受到异国风情，非常受各国游客欢迎。\n\n比如被认为是构思歌剧《蝴蝶夫人》灵感来源的哥拉巴住宅，日本最古老的哥特式教会“大浦天主堂”。16世纪从葡萄牙传来的糕点"长崎蛋糕（カステラ）"等等，外国风的建筑和饮食文化流传下来，吸引着大家。\n\n白天逛完景点后，进入夜晚的长崎，也有不容错过的精彩哦。那便是和香港，摩纳哥并称的，世界新三大夜景的长崎夜景喽。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50518.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50519.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50520.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/16-50521.webp"]'::jsonb, E'2018-04-03'::timestamptz, E'长崎市'),
(E'https://matcha-jp.com/cn/4270', E'zh-Hans', 42, E'【长崎县】从天守阁望出去的景色魅力十足！“平户城”的推荐景点', E'拥有日本最古老西洋贸易港的港都，长崎县平户市。这里有一座被选为“日本100名城”之一的“平户城”。这次要介绍的是平户城的景点及其周边的观光景点。\n\n平戸城是位于九州岛・长崎県平戸岛的日式城堡，江戸时代时建造作为统治此地的松浦氏的居城。1718年完工。但是在1873年一度被废城，现在的建筑是1962年平戸市所复原而成。\n\n照片提供：公益财团法人 平户市振兴公社 从小山上的天守阁望出去的景色是平户城最大的看点。三面环海，可以眺望大海另一端的黑子岛上的原生林和平户大桥。也可以将平户市内尽收眼底。\n\n搭地铁从福冈西场到转运站的博德车站约5分。从博德车站搭乘特急绿(往佐世保)，首先前往佐世保车站。乘车时间约2小时，自由座车资3,360日元。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/04/10-23858.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/10-23857.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/10-23859.webp"]'::jsonb, E'2017-09-29'::timestamptz, E'平戸市'),
(E'https://matcha-jp.com/cn/20733', E'zh-Hans', 43, E'【熊本】「天草」观光推荐景点5选！两天一夜示范行程介绍', E'针对计划前往天草观光旅行的人，我们将详细介绍天草的代表性美食景点、历史集落等推荐观光景点。此外，我们还将介绍两天一夜的模范行程和推荐的饭店，同时解答关于天草的各种疑问。\n\n天草由美丽的岛屿组成，是一个拥有丰富自然和历史魅力的地区。本文将详细介绍天草的观赏景点，如赏鲸活动、享受新鲜海味美食、历史古村等。\n\n天草位于熊本县西南部，由约120个岛屿组成。它与九州本土连接，拥有丰富的自然环境和美丽海域。天草以鲜味如虾和海胆等新鲜海味闻名，吸引许多游客造访。\n\n此外，天草也以历史悠久的地方闻名，潜伏基督徒历史以及岛原之乱等事件皆为人所熟知。造访天草时，您可以从自然、历史，到美食等多个角度充分享受其魅力。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189751.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189750.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189752.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189753.webp"]'::jsonb, E'2024-08-01'::timestamptz, E'熊本市'),
(E'https://matcha-jp.com/cn/8680', E'zh-Hans', 43, E'来熊本县的6大景点，体验四季风光及品尝美味传统料理！', E'日本超人气熊本熊可不仅仅是创意角色哦。他可是熊本县正式的营业部长，为大家亲切介绍熊本县的美景和美食。熊本县内，不仅有熊本城这样的历史名胜，也有温泉乡这样的疗愈景点。但其优美的自然环境，与暖暖的乡土料理也是熊本如此受欢迎的原因之一。接下来就让小编带着你，在熊本的自然里漫步，还有美食等着你哦。\n\n在日本国内外都拥有超高人气的熊本熊本职其实是熊本县的营业部长，肩负宣传熊本的旅游及特产，是名副其实的公务员哦！\n\n但让除了熊本熊的宣传外，位于九州地区中部的熊本县，本身就是自然景观优美，旅游休闲的绝佳选择。县内不仅有自然名胜阿苏山，还有日本观光不可缺少的火山温泉。从春季的樱花到秋季的红叶，熊本的四季为你展现出日本自然与人文完美结合的特质。\n\n根子岳是阿苏五岳之一。阿苏五岳是对日本著名活火山阿苏山脉的5个核心山体的统称。自古以来就是当地人民心灵与信仰的寄托。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/12/19-93586.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/11-92793.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/11-92801.webp","https://resources.matcha-jp.com/resize/720x2000/2019/12/11-92865.webp"]'::jsonb, E'2020-01-05'::timestamptz, E'熊本城'),
(E'https://matcha-jp.com/cn/6934', E'zh-Hans', 43, E'【熊本】走入深绿异世界的梦幻景点“上色见熊野座神社”', E'上色见熊野座神社为日本的人气少女漫画《萤火之森（蛍火の杜へ）》的故事舞台，带点灰暗气息的深绿森林仿佛能将人们引导至妖怪居住的山神森林。其特殊的神秘气息三番两次在日本的推特与IG上面造成话题，就让小编来揭开此座神社的神秘面纱吧！\n\n一提到熊本，十之八九的人会想到腹地辽阔、景观壮丽的阿苏火山，但近几年在日本的IG与推特上，流传着一处足以凌驾阿苏美景的超私密能量景点【上色见熊野座神社】。就让我们一起来看看日本乡民口中的话题景点到底有多厉害吧！\n\n能够将如此冷门的熊本景点完美融入漫画作品当中，想必是出身于熊本县的绿川大师才构思得出来的创作点子！这几年在IG与推特等SNS媒体的推波助澜之下，让上色见熊野座神社屡屡成为日本网路乡民所瞩目的拍摄景点。\n\n从入口处大约向上行走约10分钟后，即可看到小而玲珑的神殿（本殿）。上色见熊野座神社供奉了伊邪那岐命、伊邪那美命、石君大将军（※注)这三位神明。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/12/25-68559.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/25-68560.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/25-68561.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/25-68571.webp"]'::jsonb, E'2019-01-22'::timestamptz, E'阿苏'),
(E'https://matcha-jp.com/cn/7931', E'zh-Hans', 44, E'【大分景点】日本取水客的必访圣地！由布院碳酸气泡水“白水矿泉”', E'位在九州的大分县，是出名的温泉县。大分一带天然水源丰沛，除了温泉以外，可以饮用的天然涌泉也很多。这次来到大分县的由布市，知名的汤布院温泉乡的近郊处，天然涌出的碳酸气泡水“白水矿泉”。\n\n提到大分县的由布市，相信许多人都会联想到知名的汤布院温泉。其实由布市除了泡的温泉，还有可饮用的天然涌泉，今天就来介绍其中一处白水矿泉。\n\n日本全国可饮用的天然涌出碳酸气泡水不多，而大分县由布市的白水矿泉更是只占日本涌泉中百分之一的单纯碳酸泉※，碳酸成分较高。而碳酸水流动时的气泡让水看起来像是白​​色的，因此得名白水。\n\n古时这里的碳酸泉水被认为能够治百病，因此当时便相当受欢迎。大正时期还曾指定贩售白水矿泉的碳酸水给海军作为饮用水。时至今日，即便不为传闻的功效，顺口好喝的天然碳酸水仍让取水饮用的人络绎不绝。许多外地的取水客不辞辛劳到访，停车场可以看到来自日本各处的车牌号码。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/12-85866.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/12-85867.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/12-85868.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/19-86368.webp"]'::jsonb, E'2019-10-10'::timestamptz, E'由布市'),
(E'https://matcha-jp.com/cn/7395', E'zh-Hans', 44, E'别府由布院…九州大分一定不要错过的的十五个景点及美食', E'大分县有许多很棒很棒的观光景点，例如别府和由布院等。大家一定要来感受一下大分县的温泉，美食，大自然及寺院神社等地方，本篇文章相会介绍到大分一地要走访的十五个观光景点及必吃的美食！\n\n九州地方的大分县别府及由布院(※1)是一个有观光地满载的地方。这次小编要来介绍的是大分一定要走访的十五个景点及要尝试的美食。\n\n※1：由布院(ゆふいん)……由布院有两种表记名称，分别为“由布院”及“汤布院”，车站等会是标示成“由布院”。本篇文章除了固有名词吃外，会以“由布院”来表记。\n\n若从福冈县前往大分别府或由布院的话可以搭观光列车“特急由布院之森”。另外若想要同时也走访熊本县，长崎县，鹿儿児岛县等九州的观光景点，建议可以购买“JR Kyushu Rail Pass”。此车票有分成九州全域，北部，南部f区，如果想要包含大分的话应选择“九州全域”及“北部”区域。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75877.jpeg","https://resources.matcha-jp.com/resize/720x2000/2019/05/13-76699.jpeg","https://resources.matcha-jp.com/resize/720x2000/2019/05/13-76724.jpeg","https://resources.matcha-jp.com/resize/720x2000/2019/05/13-76701.jpeg"]'::jsonb, E'2019-07-10'::timestamptz, E'别府市'),
(E'https://matcha-jp.com/cn/5778', E'zh-Hans', 40, E'九州该怎么玩最划算？买张“JR九州PASS”来吃尽美食、看尽美景吧', E'前往九州自助旅行时，若想要节省交通费用的话，买张“JR九州铁路周游券”可说是征服九州交通的入门必备。小编要教你购票方式、价格、种类，包括全九州版、北九州、南部九州以及如何在5天内环绕九州来购物、吃美食、看美景！\n\n针对“短期停留”的外国籍观光客所发行的交通套票。只要持“全九州版”周游券即可搭乘九州地区的普通列车、特快列车、新干线（博多～鹿儿岛中央）※。当然“由布院之森”号、“坐A列车去吧！”等九州地区极具代表性的特快列车，也可划位预约哦！ ※小仓～博多区域的新干线因属于山阳新干线，因此无法搭乘。\n\n目前周游券依照使用区域分为“全九州版铁路周游券”、“北部九州版铁路周游券”、“南部九州版铁路周游券”。\n\n海外购买 想要使用此张周游券的人，可以事先透过日本海外配合的旅行社进行购买，并于抵达日本之后再到JR车站的“みどりの窓口（绿色窗口）”进行PASS的兑换。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/02/17-48404.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/16-48342.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/16-48343.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/16-48344.webp"]'::jsonb, E'2018-08-22'::timestamptz, E'北九州市'),
(E'https://matcha-jp.com/cn/10212', E'zh-Hans', 44, E'【大分】抚摸历史印记，回归自然本心。完美的非日常之旅', E'大分县以别府，汤布院等温泉胜地而闻名。其南部，有壮观的景点，地质公园，历史悠久的街道，自然孕育的独特文化。今天我们要来介绍位于臼杵，佐伯，津久见，豊后大野的10景，以及美食和住宿！\n\n大分县因为别府温泉，，汤布院而被称为‘温泉县“。朝南玩下去，就可以欣赏到壮丽的山海风光，世界文化遗产和美食。\n\n16世纪时，臼杵市是葡萄牙和中国商人来往的国际港都。您可以在街道上感受多个时代的历史痕迹，可以在每个转角邂逅新的发现。\n\n臼杵石佛是从平安时代后期到镰仓时代(1185～1333年)在山的岩壁表面雕刻的佛像。当时净土宗盛行，人们梦想着去极乐净土，用各种方式表达自己的愿望。 在石佛群前的公园一带，大约在江戸时代(1603～1868年)初期之前有一个小湖。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108692.webp","https://resources.matcha-jp.com/resize/720x2000/2020/10/28-108689.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/10-110690.webp"]'::jsonb, E'2021-01-04'::timestamptz, E'别府温泉'),
(E'https://matcha-jp.com/cn/7355', E'zh-Hans', 45, E'网红打卡圣地！九州・宮崎一定不能错过的10个景点&8种美食', E'位于九州南部的宫崎县，是气候温暖，被美丽大海和丰富自然所包围的地区。县内有高千穂峡谷，青岛神社等可以拍出美丽照片的景点，又有诸如芒果、宫崎牛等各种美食。这篇文章就为大家介绍在宫崎县不能错过的美景和美食。\n\n由于从国内没有航班直达宫崎县，只能先飞往羽田机场或其他日本国内机场转机。宮崎机场距离宮崎市中心非常近。\n\n如果是从九州地区其他县前往的话，有大巴和铁路可以选择。从博多（福冈县）搭乘高速大巴只需要大约4个半小时即可到达了(4,630日币)。\n\n在宮崎县内也有电车、巴士运行，不过由于宫崎县面积较大，所以移动起来还是租车比较方便。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75848.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75843.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75844.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75845.webp"]'::jsonb, E'2019-06-06'::timestamptz, E'高千穂峡'),
(E'https://matcha-jp.com/cn/7488', E'zh-Hans', 45, E'【宫崎】“高千穗がまだせ市场”精选人气伴手礼7选！', E'以充满仙气的“峡谷”景观而闻名世界的高千穗，除了是个自然景观丰富的观光宝库之外，海拔300多公尺高的地形间接孕育出了不同于平地的食材。若不想东奔西跑来买齐高千穗伴手礼的话，就得来一趟在地人也每天逛的蔬果土产商店“高千穂がまだせ市场”。\n\n于九州宫崎县北方的高千穗是日本国民公认的绝景圣地，来到了高千穗除了可以租借小船来畅游凉爽的高千穗峡谷，也可以漫步于充满古代气息的天岩戸神社、天安河原等能量景点，抑或是预约一间可以泡汤的日式旅馆来彻底放空。\n\n“高千穗がまだせ市场”为一栋复合式的商业观光设施，里头包含了可以购卖地产蔬果、各式加工土产的“鬼八之藏（鬼八の蔵）”、可享用高千穗牛料理的“和餐厅（レストラン和）”，以及可以直接购买高千穗牛肉的“JA高千穗地区肉品中心（JA高千穂地区ミートセンター）”。\n\n而作为设施名称的“がまだせ”则为当地的方言，含有“提起精神！加油！”的意思，也同时意味着高千穗地区想要“使用当地特产来振地观光”的抱负与期盼。本篇的重点将放在可以购买当地各种特产品的“鬼八之藏”，以下将进行详细的商店介绍。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/23-77552.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/30-78205.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/30-78207.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/30-78208.webp"]'::jsonb, E'2019-07-02'::timestamptz, E'宫崎市'),
(E'https://matcha-jp.com/cn/6263', E'zh-Hans', 45, E'【宫崎县】到高千穂旅游必做的6件事', E'“高千穗”位于宫崎县的北边。面积虽不大，却有着自然景观丰富的峡谷，以及许多神话流传的历史轨迹，是许多观光客探访的热门景点。这回，我们要来解开高千穗之所以吸引人的魅力所在，并告诉大家一定不能错过的地方有哪些。\n\n宫崎县的高千穗这里流传着日本草创时期的故事，也就是“日本神话”(※1)的起源地而闻名。这项传说发迹于这个自然景观丰富的地方，直到现在，高千穗仍是许多传说的背景所在。\n\n这回，我们就要以这里的“大自然景观”与“历史”为起点，告诉大家哪里可以体验到高千穗的魅力。\n\n※1：日本神话……《古事记》、《日本书纪》等古书上描述日本的形成，以及日本天皇的历史。神人结合，古代日本人们生活的景象。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/28-57269.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/29-57280.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/29-57281.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/28-57274.webp"]'::jsonb, E'2018-09-25'::timestamptz, E'高千穂町'),
(E'https://matcha-jp.com/cn/3072', E'zh-Hans', 46, E'【2024年最新版】鹿儿岛旅游完全攻略 必走访景点，美食，最新流行', E'鹿儿岛拥有景色壮观的樱岛，指宿温泉沙浴，屋久岛及奄美大岛等离岛，以及吃了还想再吃的绝品美食！ 也曾作为大河剧《西郷殿》的剧场，去了一次一定会被鹿儿岛的魅力俘虏。本篇文章相会介绍鹿儿岛一定要做的事，要吃的美食，交通方式，天气及合适的服装等，最新的观光资讯。\n\n海鲜及当地美食、各种特色的温泉和使身心疗癒的大自然、还有热情温暖的当地居民……。\n\n只要去了一次，就还会想再来，听说有不少的人为探其所有魅力，造访多次鹿儿岛。那麽赶快来认识一下鹿儿岛的魅力所在吧！\n\n位于市中心的鹿儿岛市街地区耸立着一座樱岛，是鹿儿岛的象徵。雾岛区内有雾岛温泉乡，是一个具有代表性的观光地区。指宿区还有砂温泉。如果从九州本土可以搭船或飞机到屋久岛和奄美大岛等离岛。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/09-76450.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/09-76452.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/09-76498.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/09-76453.webp"]'::jsonb, E'2017-10-25'::timestamptz, E'指宿温泉'),
(E'https://matcha-jp.com/cn/6679', E'zh-Hans', 46, E'鹿儿岛的代表性观光景点！——畅游“仙岩园”的8点要诀', E'“仙岩园”是鹿儿岛的代表性庭园。作为樱岛的绝景景点、大名曾经生活的宅邸、可以体验鹿儿岛历史和文化的景点等，这儿有很多看点。它还是电视剧的拍摄地，本文详解这一越来越受关注的仙岩园的魅力！\n\n要提鹿儿岛代表性的观光景点的话，那就是“仙岩园(Senganen)”。这是一个占地达50,000平方米的开阔庭园。\n\n从鹿儿岛的中心地段搭乘直达巴士约40分左右即可到达。连续几日都游人如织，十分热闹。\n\n仙岩园虽以庭园之美而知名，其他的景点还有很多，如可以体验大名生活起居的御殿、近距离观赏传统工艺品制作风貌的工坊等。有很多令人想要花上一番时间仔细游览的景点。这里还是2018年日本大河电视剧(※1)《西乡(Sego)殿》的拍摄地，日渐受到人们关注。 本文为大家传达最大限度地畅游仙岩园的8点要诀！', E'["https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65761.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65754.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/09-69126.webp","https://resources.matcha-jp.com/resize/720x2000/2018/11/04-65759.webp"]'::jsonb, E'2019-07-22'::timestamptz, E'知名町'),
(E'https://matcha-jp.com/cn/4985', E'zh-Hans', 46, E'『鹿儿岛』到JR日本最南端车站招唤幸福！黄色邮筒＆幸福之钟传说', E'每每说到“日本最南端”这种称呼，总是令人有所幻想，而传说中的JR日本最南端车站就在鹿儿岛的“西大山站”，一个历史感十足，因为黄色邮筒＆幸福之钟传说，人气从来不减的无人车站。今天，它仍旧在九州南端运作，看尽不同在鹿儿岛来来去去的乘车过客。\n\n西大山站位于鹿儿岛，最为人所熟悉的便是“JR日本最南端”火车站的称号。很多旅客都会慕名而去。虽然是无人车站，但至今仍照常运作，只是通往此处的班次不多，例如指宿枕崎线山川·指宿方向，一天约只有8班列车驶往，大家如果选择搭乘列车的话，可以好好安排参观的时间长短，以及留意上车时间。\n\n西大山站，是日本JR九州指宿枕崎线的尾站，自1960年开业至今，一直都是日本JR铁路中最南方的车站，享负盛名。自从2003年冲绳的单轨电车开始行驶后，便正式更名为“JR日本最南端の駅”，自此便“站”如其名。\n\n虽然现在看似很风光很有人气，可是曾经的西大山站却曾有被停用废弃的危机，由于当时的载客量不足，所以险些被停用。不过，幸好最后还是被保留下来，继续传承着“日本最南端”这个名号，也幸好现在游客不断，让西大山站还能活跃至今。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35218.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35220.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35217.webp","https://resources.matcha-jp.com/resize/720x2000/2017/09/01-35221.webp"]'::jsonb, E'2017-10-24'::timestamptz, E'指宿市'),
(E'https://matcha-jp.com/cn/2940', E'zh-Hans', 47, E'日本人的度假胜地， 冲绳旅游全攻略', E'说到冲绳，它是由160个离岛及冲绳本岛组成，为日本最南边的县。温暖气候，丰富大自然，白色沙滩，不同于日本本岛的美食。是海内外旅客争相向往的日本渡假胜地。这篇要介绍往冲绳的交通方式、观光景点、美食、饭店等信息。\n\n说到冲绳 冲绳县是由冲绳本岛及160个离岛构成，是日本最南边的县。冲绳本岛及其离岛，多为白色沙滩。毎年吸引近700万以上的观光客来到这里，可说是亚洲代表的渡假天堂。\n\n从东京飞那霸，距离约2,100km；距北京1,900km、首尔1,300km左右，这些地方都有直航班机，约2～3小时就能抵达那霸。距离台湾更近，仅750km左右，直达航班更是1个半小时就能到达。对于亚洲地方的国家来说，冲绳可以说是相当方便的国外旅游胜地。\n\n冲绳地处副热带地区，不同于日本本岛是温带。气候温暖是它的一大特征，也是鳯梨等热带水果及甘蔗的盛产地。', E'["https://resources.matcha-jp.com/archive_files/jp/2016/01/tokyo_to_nagoya_20160125c.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/30-124771.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/30-124772.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/30-124773.webp"]'::jsonb, E'2017-05-17'::timestamptz, null),
(E'https://matcha-jp.com/cn/11764', E'zh-Hans', 47, E'【冲绳】宛如豪华度假村一般！来【AEON永旺梦乐城 冲绳来客梦】收获冲绳无限魅力', E'作为冲绳最大的购物中心【AEON永旺梦乐城 冲绳来客梦】无论是从机场，还是市内均有巴士可可以抵达，交通十分便利。中心内有宝可梦中心等200家以上的店家进驻，加上免税服务完善，无论是刚抵达冲绳想先过过购物瘾、还是回国前想再买点伴手礼送人都很推荐。\n\n首次降落冲绳的游客无需担心，有多种方式可以前往【AEON永旺梦乐城 冲绳来客梦】，不只是从那霸机场就能搭乘高速直达，网罗本岛南部到北部的路线巴士也都有停靠。\n\n进驻【AEON永旺梦乐城 冲绳来客梦】的商家店铺超过200家，除了大型超市之外，服装品牌、生活杂货、药妆店、餐厅等各类型不同的店家应有尽有，正门入口处的大水槽更是人气的拍照地点，虽然缤纷的热带鱼儿们是主角，但随着季节变换的装饰也是一大亮点。\n\n访日观光客们在外购物时最在意的免税服务也很完善，【AEON永旺梦乐城 冲绳来客梦】半数以上的店铺都能够直接免税，对游客来说非常方便。超市的AEON STYLE区里中设有多家适合选购伴手礼的店，当地的小点心、泡盛、茶叶及冲绳特有的食材都很值得一逛！', E'["https://resources.matcha-jp.com/resize/720x2000/2023/12/07-155419.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/05-155036.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155195.webp","https://resources.matcha-jp.com/resize/720x2000/2023/11/30-154380.webp"]'::jsonb, E'2023-12-21'::timestamptz, null),
(E'https://matcha-jp.com/cn/6190', E'zh-Hans', 47, E'冲绳玄关口 — 那霸市推荐景点7选', E'冲绳县内人口密度最高的那霸市，是冲绳的公家机关及办公室密集的商办街道，也是饮食店、饭店林立的观光都市，更是吃美食、血拼购物，冲绳No.1的闹区。\n\n冲绳县的天空之门，那霸机场所在地—那霸市，还留有琉球王朝时期(※1)的街道名称「首里の街」、因为访日旅客而热闹非凡的「国际通り」、区域整合规划后的「那霸新都心」等，有都会区的热闹繁华，也有怀旧的商业区可以悠哉散步的观光胜地。\n\n市区之内可以搭乘冲绳都市轨道电车行动。也有往返离岛的船班，随时都可以出发住一晚，交通非常方便。\n\n※1：琉球王朝时期……1429年起，至1879年止，约450年左右，统治冲绳的琉球王朝。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55846.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55837.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55836.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55838.webp"]'::jsonb, E'2018-07-26'::timestamptz, null)
